package hotel.notifications;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import hotel.EmptyDatabase;
import hotel.messages.EmailSender;
import hotel.messages.Message;
import hotel.messages.SentMessages;
import hotel.reservations.Guest;
import hotel.reservations.NewReservation;
import hotel.reservations.PriceCalculator;
import hotel.reservations.RatePlan;
import hotel.reservations.Reservation;
import hotel.reservations.ReservationService;
import hotel.reservations.ReservationStore;
import hotel.rooms.Rooms;
import java.time.LocalDate;
import java.util.List;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class StaffNotificationsTest {

    private final EmptyDatabase database = new EmptyDatabase();
    private final SentMessages sentMessages = new SentMessages(database.dataSource());
    private final EmailSender emailSender = new EmailSender(sentMessages);
    private final ReservationService service = new ReservationService(
            new Rooms(database.dataSource()), new ReservationStore(database.dataSource()), new PriceCalculator(),
            List.of(new HousekeepingNotifier(emailSender), new FinanceNotifier(emailSender)));

    @AfterEach
    void closeDatabase() {
        database.close();
    }

    private Reservation book(int room, RatePlan plan) {
        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
        return service.create(new NewReservation(
                room, guest, LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-13"), 2, plan));
    }

    private Message sentTo(String address, String subject) {
        return sentMessages.all().stream()
                .filter(m -> m.to().equals(address) && m.subject().equals(subject))
                .findFirst()
                .orElseThrow(() -> new AssertionError("no e-mail to " + address + ": " + subject));
    }

    @Test
    void confirmingTellsHousekeepingAndFinance() {
        Reservation reservation = book(201, RatePlan.STANDARD);

        service.confirm(reservation.id());

        assertEquals(2, sentMessages.all().size());
        String housekeeping = sentTo("governanca@pousadamarealta.com.br", "Reserva confirmada - quarto 201").body();
        assertTrue(housekeeping.contains("10/03/2027"));
        assertTrue(housekeeping.contains("13/03/2027"));
        assertTrue(housekeeping.contains("Hóspedes: 2"));
        String finance = sentTo(
                "financeiro@pousadamarealta.com.br", "Pagamento recebido - reserva " + reservation.id()).body();
        assertTrue(finance.contains("R$ 1.049,16"), finance);
    }

    @Test
    void cancellingAConfirmedReservationTellsHousekeepingAndFinanceTheRefund() {
        Reservation reservation = book(201, RatePlan.STANDARD);
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        assertEquals(4, sentMessages.all().size());
        String housekeeping = sentTo("governanca@pousadamarealta.com.br", "Reserva cancelada - quarto 201").body();
        assertTrue(housekeeping.contains("10/03/2027"));
        assertTrue(housekeeping.contains("13/03/2027"));
        String finance = sentTo("financeiro@pousadamarealta.com.br", "Reembolso - reserva " + reservation.id()).body();
        assertTrue(finance.contains("R$ 1.049,16"), finance);
    }

    @Test
    void withNothingToRefundFinanceIsNotTold() {
        Reservation reservation = book(201, RatePlan.NON_REFUNDABLE);
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        assertEquals(3, sentMessages.all().size());
        sentTo("governanca@pousadamarealta.com.br", "Reserva cancelada - quarto 201");
    }

    @Test
    void cancellingAPendingReservationTellsNobody() {
        Reservation reservation = book(201, RatePlan.STANDARD);

        service.cancel(reservation.id());

        assertTrue(sentMessages.all().isEmpty());
    }
}
