        assertTrue(finance.contains("R$ 1.049,16"), finance);
    }

    @Test
    void cancellingAConfirmedReservationTellsHousekeepingAndFinanceTheRefund() {
        Reservation reservation = book(201, RatePlan.STANDARD);
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        assertEquals(4, sentMessages.all().size());
        String housekeeping = sentTo("governanca@pousadamarealta.com.br", "Reserva cancelada - quarto 201").body();
        assertTrue(housekeeping.contains("10/03/2027"));
        assertTrue(housekeeping.contains("13/03/2027"));
        String finance = sentTo("financeiro@pousadamarealta.com.br", "Reembolso - reserva " + reservation.id()).body();
        assertTrue(finance.contains("R$ 1.049,16"), finance);
    }

    @Test
    void withNothingToRefundFinanceIsNotTold() {
        Reservation reservation = book(201, RatePlan.NON_REFUNDABLE);
        service.confirm(reservation.id());

        service.cancel(reservation.id());

        assertEquals(3, sentMessages.all().size());
        sentTo("governanca@pousadamarealta.com.br", "Reserva cancelada - quarto 201");
    }

    @Test
    void cancellingAPendingReservationTellsNobody() {
        Reservation reservation = book(201, RatePlan.STANDARD);

        service.cancel(reservation.id());

        assertTrue(sentMessages.all().isEmpty());
    }
